jsLibrary.killInstallBanner:
// Remove "Open in app" / "Use the app" prompts on Instagram and YouTube mobile web.
(function () {
  const PHRASES = ['Open in app', 'Open app', 'Open App', 'Use the app', 'Use app', 'Open Instagram', 'Get the app', 'Get app'];
  // Whole overlays/dialogs: hide the element itself.
  const DIALOGS = [
    'ytm-mealbar-promo-renderer',
    'ytm-upsell-dialog-renderer',
    '.upsell-dialog',
    'ytm-app-upsell-renderer',
  ];
  // App-store / deep links: hide just the button wrapping them, never the bar they sit in.
  const LINKS = [
    'a[href^="intent://"]',
    'a[href*="apps.apple.com"]',
    'a[href*="itunes.apple.com"]',
    'a[href*="play.google.com/store"]',
    'a[href*="redirect_app_store_ios"]',
    'a[href^="instagram://"]',
    'a[href^="youtube://"]',
    'a[href^="vnd.youtube"]',
  ];
  function hide(el) {
    if (!el || el.__foBanner) return;
    el.__foBanner = true;
    el.style.setProperty('display', 'none', 'important');
  }
  function buttonShell(el) {
    return el.closest('ytm-button-renderer, button, [role="button"]') || el;
  }
  function sweep() {
    for (const sel of DIALOGS) document.querySelectorAll(sel).forEach(hide);
    for (const sel of LINKS) document.querySelectorAll(sel).forEach((el) => hide(buttonShell(el)));
    document.querySelectorAll('button, a, div[role="button"]').forEach((el) => {
      if (el.__foChecked) return;
      const t = (el.textContent || '').trim();
      if (t.length > 40) return;
      el.__foChecked = true;
      if (PHRASES.some((p) => t === p)) hide(buttonShell(el));
    });
  }
  window.__feedoff && window.__feedoff.onSweep(sweep);
  sweep();
})();

jsLibrary.noAutoplayNext:
// YouTube: pause when a video ends and keep the Autoplay toggle off.
(function () {
  if (!/youtube\.com$/.test(location.hostname)) return;
  function killAutonav() {
    document.querySelectorAll('.ytm-autonav-toggle-button-container[aria-pressed="true"], button[aria-label*="Autoplay is on"]').forEach((b) => {
      try { b.click(); } catch (_) {}
    });
  }
  function hook(video) {
    if (video.__foHooked) return;
    video.__foHooked = true;
    video.addEventListener('ended', () => {
      try { video.pause(); } catch (_) {}
      killAutonav();
    });
  }
  function sweep() {
    document.querySelectorAll('video').forEach(hook);
    killAutonav();
  }
  window.__feedoff && window.__feedoff.onSweep(sweep);
  sweep();
})();

jsLibrary.oneVideoOnly:
// On a single reel/short page (/reel/ID or /shorts/ID), watch that one video only:
// block the vertical swipe that loads the next one.
(function () {
  const RX = /^\/(reel|shorts)\/[A-Za-z0-9_-]+/;
  function onSingle() { return RX.test(location.pathname); }
  function idOf(p) { const m = RX.exec(p); return m ? m[0] : null; }
  let startId = idOf(location.pathname);

  function block(e) {
    if (!onSingle()) return;
    // Let taps and horizontal drags through; stop vertical drags that page to the next video.
    if (e.type === 'touchmove' || e.type === 'wheel') {
      e.stopImmediatePropagation();
      e.preventDefault();
    }
  }
  document.addEventListener('touchmove', block, { capture: true, passive: false });
  document.addEventListener('wheel', block, { capture: true, passive: false });

  // If the site still advances via pushState, step back to the video we opened.
  const origPush = history.pushState.bind(history);
  const origReplace = history.replaceState.bind(history);
  function guard(url) {
    try {
      const p = new URL(url, location.href).pathname;
      const next = idOf(p);
      if (startId && next && next !== startId) return false;
      if (!startId) startId = next;
    } catch (_) {}
    return true;
  }
  history.pushState = function (s, t, url) { if (url && !guard(url)) return; return origPush(s, t, url); };
  history.replaceState = function (s, t, url) { if (url && !guard(url)) return; return origReplace(s, t, url); };
  window.addEventListener('popstate', () => { startId = idOf(location.pathname); });
})();

jsLibrary.ytAdPrune:
// YouTube: remove ad slots from the player data before the player ever sees them.
// Runs at document start. Gated by the "ads" toggle via window.__feedoff.enabled.
(function () {
  if (!/youtube\.com$/.test(location.hostname)) return;
  var FO = window.__feedoff;
  function on() { return !FO || !FO.enabled || FO.enabled.indexOf('ads') !== -1; }
  var KEYS = ['adPlacements', 'playerAds', 'adSlots', 'adBreakHeartbeatParams', 'adBreakParams', 'adParams'];
  function prune(o) {
    if (!o || typeof o !== 'object') return o;
    try {
      for (var i = 0; i < KEYS.length; i++) if (KEYS[i] in o) delete o[KEYS[i]];
      if (o.playerResponse) prune(o.playerResponse);
      if (o.playerConfig && o.playerConfig.daiConfig) delete o.playerConfig.daiConfig;
    } catch (e) {}
    return o;
  }
  var origParse = JSON.parse;
  JSON.parse = function () { var r = origParse.apply(this, arguments); return on() ? prune(r) : r; };
  if (window.Response && Response.prototype.json) {
    var origJson = Response.prototype.json;
    Response.prototype.json = function () {
      return origJson.apply(this, arguments).then(function (r) { return on() ? prune(r) : r; });
    };
  }
  var initial;
  try {
    Object.defineProperty(window, 'ytInitialPlayerResponse', {
      configurable: true,
      get: function () { return initial; },
      set: function (v) { initial = on() ? prune(v) : v; },
    });
  } catch (e) {}
})();

jsLibrary.ytAdSkip:
// YouTube: if an ad still plays, mute it and jump to its end; click Skip/close when offered.
(function () {
  if (!/youtube\.com$/.test(location.hostname)) return;
  var FO = window.__feedoff;
  function on() { return !FO || !FO.enabled || FO.enabled.indexOf('ads') !== -1; }
  var wasMuted = null;
  function tick() {
    if (!on()) return;
    var ad = document.querySelector('.ad-showing, .ad-interrupting, .ytp-ad-player-overlay, ytm-player-ad-overlay, .ytp-ad-preview-container');
    var v = document.querySelector('video');
    if (ad && v) {
      if (wasMuted === null) wasMuted = v.muted;
      v.muted = true;
      if (isFinite(v.duration) && v.duration > 0) { try { v.currentTime = v.duration; } catch (e) {} }
      try { v.playbackRate = 16; } catch (e) {}
    } else if (v && wasMuted !== null) {
      v.muted = wasMuted; wasMuted = null;
      try { if (v.playbackRate === 16) v.playbackRate = 1; } catch (e) {}
    }
    var skip = document.querySelector('.ytp-ad-skip-button, .ytp-ad-skip-button-modern, .ytp-skip-ad-button, button.ytm-skip-ad-button, [class*="skip-button"], [id*="skip-button"]');
    if (skip) { try { skip.click(); } catch (e) {} }
    var close = document.querySelector('.ytp-ad-overlay-close-button, .ytm-ad-overlay-close');
    if (close) { try { close.click(); } catch (e) {} }
  }
  setInterval(tick, 400);
  FO && FO.onSweep(tick);
})();

jsLibrary.ytSignInHint:
// YouTube: the Subscriptions page is empty when signed out. Show a hint instead of a blank screen.
(function () {
  if (!/youtube\.com$/.test(location.hostname)) return;
  var ID = '__feedoff_yt_hint';
  function hasContent() {
    return !!document.querySelector('ytm-section-list-renderer, ytm-item-section-renderer, ytm-rich-grid-renderer, ytm-watch, ytm-search');
  }
  function signedIn() {
    return !!document.querySelector('ytm-profile-icon img, img.avatar, [aria-label*="Account"] img');
  }
  function show() {
    if (document.getElementById(ID)) return;
    var box = document.createElement('div');
    box.id = ID;
    box.style.cssText = 'position:fixed;left:16px;right:16px;top:45%;transform:translateY(-50%);padding:22px 18px;border-radius:16px;background:rgba(127,127,127,.12);text-align:center;font:15px/1.45 -apple-system,system-ui,sans-serif;color:inherit;z-index:2147483000;';
    var t = document.createElement('div'); t.style.cssText = 'font-weight:700;font-size:17px;margin-bottom:6px;'; t.textContent = 'Sign in to see your subscriptions';
    var s = document.createElement('div'); s.style.cssText = 'opacity:.75;margin-bottom:14px;'; s.textContent = 'YouTube Lite opens on Subscriptions instead of the Home feed. Sign in once and it stays signed in.';
    var a = document.createElement('a');
    a.href = 'https://accounts.google.com/ServiceLogin?service=youtube&continue=' + encodeURIComponent('https://m.youtube.com/feed/subscriptions');
    a.textContent = 'Sign in';
    a.style.cssText = 'display:inline-block;padding:10px 22px;border-radius:999px;background:#FF6B4A;color:#fff;font-weight:600;text-decoration:none;';
    box.appendChild(t); box.appendChild(s); box.appendChild(a);
    document.body.appendChild(box);
  }
  function hide() { var b = document.getElementById(ID); if (b) b.remove(); }
  function check() {
    var onSubs = /^\/feed\/subscriptions/.test(location.pathname);
    if (onSubs && !hasContent() && !signedIn()) show(); else hide();
  }
  setTimeout(check, 2500);
  window.__feedoff && window.__feedoff.onSweep(check);
})();
